#[cfg(feature = "wide")]
#[test]
fn wide_threefry32x2x4_all_lanes_and_counter_carries() {
    let mut scalars: [Threefry32x2; 4] = std::array::from_fn(|lane| Threefry32x2 {
        c: wrap![u32::MAX;2],
        k: std::array::from_fn(|i| {
            wrap!(if i == 2 {
                (0..2).fold(0x1bd11bda, |a, j| a ^ w32(lane, j))
            } else {
                w32(lane, i)
            })
        }),
        buf: wrap![0;2],
        pos: wrap!(2),
    });
    let mut vector = crate::wide::Threefry32x2x4 {
        c0: unsafe {
            std::mem::transmute::<[u32; 4], _>(std::array::from_fn(|lane| *scalars[lane].c[0]))
        },
        c1: unsafe {
            std::mem::transmute::<[u32; 4], _>(std::array::from_fn(|lane| *scalars[lane].c[1]))
        },
        k0: unsafe {
            std::mem::transmute::<[u32; 4], _>(std::array::from_fn(|lane| *scalars[lane].k[0]))
        },
        k1: unsafe {
            std::mem::transmute::<[u32; 4], _>(std::array::from_fn(|lane| *scalars[lane].k[1]))
        },
        k2: unsafe {
            std::mem::transmute::<[u32; 4], _>(std::array::from_fn(|lane| *scalars[lane].k[2]))
        },
        buf0: unsafe { std::mem::transmute([0u32; 4]) },
        buf1: unsafe { std::mem::transmute([0u32; 4]) },
        pos: 2,
    };
    for _ in 0..256 {
        assert_eq!(
            vector.nextu(),
            std::array::from_fn(|lane| scalars[lane].nextu())
        );
    }
    assert!(vector.c1.to_array().iter().all(|&x| x == 0));
}

